solution.css:
/* The row is fixed at 400px for this exercise */
.session-row {
  width: 400px;
  display: flex;
  align-items: center;
  gap: 12px;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
}
.time {
  flex: 0 0 5rem;
  font-variant-numeric: tabular-nums;
  color: #6b7280;
}
.title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 600;
}
.save {
  flex: none;
  padding: 0.3em 0.8em;
}
